/**
 * The value of one decoded call argument.
 */
export type CallArgumentValue = string | boolean | Array<CallArgumentValue>

/**
 * What is known of one argument's value. `decoded`: `value` is present. `beyond_stored_bytes`: the argument's bytes are not in the stored head of the calldata — a dynamic argument (`bytes`, `string`, an array, a tuple holding one), or one past the head; no value is given, and none is guessed. `withheld_for_size`: no value is given for size — the value is too large to include, or it lies past the first 128 KiB of a calldata too large to decode in full (those bytes exist; they are just not decoded).
 */
export type CallArgumentValueState = "decoded" | "beyond_stored_bytes" | "withheld_for_size" | (string & {})

/**
 * How much of the calldata the decode saw. `full`: every byte of the calldata — the decode was checked end to end. `head`: only the first bytes of a longer calldata were decoded — a nested frame's `inputHead` (an argument past it is `beyond_stored_bytes`), or the first 128 KiB of a calldata larger than that (an argument past them is `withheld_for_size`); the decode could not be checked end to end.
 */
export type CallByteCoverage = "full" | "head" | (string & {})

/**
 * How far a decoded call may be trusted — the same vocabulary as decoded events' `decodeStatus`. `partial`: every known signature for the selector was tried and exactly one of the best-vouched ones fits the bytes; the arguments are its reading (signatures seen in verified contracts outrank those only submitted to public databases). `partial` because function signatures carry no parameter names — whether the whole calldata was seen is `byteCoverage`. `ambiguous`: more than one best-vouched signature fits (`fittingCount`), or one fits but not every known signature could be tried, or the only fits are submitted signatures while every verified one fails; no signature is chosen, and arguments are given only when every fitting signature has the same types. `abi_missing`: no signature is known for the selector — the argument types are unknown. `failed`: every known signature was tried and none fits these bytes.
 */
export type CallDecodeStatus = "partial" | "ambiguous" | "abi_missing" | "failed" | (string & {})

/**
 * What calldata there is to decode. `available`: there is calldata with a 4-byte selector, and `byteCoverage` and `decodeStatus` say what came of it. `none`: the input is empty — a plain value transfer. `no_selector`: not an ABI function call — shorter than 4 bytes, or a call to a precompile. `contract_creation`: the input is the init code of a contract creation, never decoded as arguments. `not_stored`: trace frames only — the frame has calldata (`inputSize` > 0) but its head was not kept, below the first block the frame schema is computed from; a transaction's own calldata is never `not_stored`. `not_available`: the calldata cannot be read right now, or a stored head is inconsistent with `inputSize`; this says nothing about the call — it is NOT "no calldata".
 */
export type CallInputStatus = "available" | "none" | "no_selector" | "contract_creation" | "not_stored" | "not_available" | (string & {})

/**
 * The first and the last block in which an address received a call.
 */
export interface CallSpan {
  /**
   * The first block in which the address received a call.
   */
  firstBlock: number
  /**
   * The last block in which the address received a call.
   */
  lastBlock: number
}

/**
 * Where a decoded call's types came from. `registry`: known function signatures, looked up by the 4-byte selector.
 */
export type CallTypeSource = "registry" | (string & {})

/**
 * How a decoded argument's `string` values are written. `hex`: a `string` inside the argument is not valid UTF-8 (the ABI does not require it), so every `string` in this argument is given as `0x` hex of its bytes.
 */
export type CallValueEncoding = "hex" | (string & {})

