/**
 * What a reference — an address, a name, a token symbol or name — resolves to: the addresses it can mean, best first, each with what TraceFast shows for it and what kind of address it is.
 */
export interface EntityResolution {
  /**
   * For a query that is a whole number: the block with that number, when TraceFast holds it. Absent when it does not — a number past the chain head, or a block in a range that is temporarily unavailable: absence is not "no such block". The same query is also looked up as text (a token can be named by digits).
   */
  block?: ResolvedBlock
  /**
   * Chain id the matches are on. `1` is Ethereum mainnet.
   */
  chainId: number
  /**
   * `true` when more addresses matched than were returned: ask with a larger `limit`, or a more specific query. There is no cursor. The list is also bounded in bytes (about 24 KiB of matches, one always given), so a list of matches carrying long texts can end before `limit` with `hasMore` true.
   */
  hasMore: boolean
  /**
   * Best first, by whose name it is, then by how closely it matched. First the addresses TraceFast presents as verified; then projects, exchanges, protocols and ENS names TraceFast knows by name — flagged ones included, since a sanctioned protocol is still the protocol asked for; then everything else that is not flagged, such as tokens known only by what they declare about themselves; last, addresses flagged as imitating an asset or flagged without a known name — shown, never hidden. Inside each group: exact, then prefix, then substring, then a match only inside a text carrying an address-like hex string; then tokens with more holders; then the shorter matching text. Empty when nothing matched.
   */
  matches: Array<ResolvedEntity>
  /**
   * The query as it was looked up: trimmed of surrounding whitespace.
   */
  query: string
  /**
   * `address` when the query is an address (`0x` + 40 hex) — the one match is that address, described; `hash` when it is `0x` + 64 hex, looked up as a transaction hash; or `text`, looked up by name and by token symbol and name.
   */
  queryKind: ResolveQueryKind
  /**
   * The collections the query was looked up in: `tokens` (token contracts by the symbol and name they declare) and `names` (the names TraceFast shows for projects, exchanges, protocols and ENS names) for a `text` query, `transactions` for a `hash` query. A collection missing from this list was not consulted for this answer, so no match in it means nothing. Absent for an address.
   */
  searched?: Array<ResolveCorpus>
  /**
   * For a `hash` query: the transaction with that hash, when TraceFast knows one. A 32-byte hash is looked up as a TRANSACTION only — a block hash is not resolved here (look a block up by its number). Absent when no transaction has that hash.
   */
  transaction?: ResolvedTransaction
}

