  /**
   * Chain id. `1` is Ethereum mainnet.
   */
  chainId: number
  /**
   * `decimals()` as declared. Absent when the contract declares none (NFTs, and some fungible tokens) — absent, never a default of 18.
   */
  decimals?: number
  /**
   * Number of addresses holding a positive balance now — the same number the holders method states. Absent when holders are not covered for this token (every NFT collection today) — absent, never zero.
   */
  holderCount?: number
  /**
   * Number of distinct addresses that have EVER held the token, including those holding nothing now. Absent where it is not available for this token.
   */
  holderCountAllTime?: number
  /**
   * `name()` as the contract declares it — verbatim, not verified: a contract may declare any text. Absent when the contract declares none. Absent when longer than 128 characters — left out whole, never shortened.
   */
  name?: string
  /**
   * Token standard as observed from its events: `erc20`, `erc721`, `erc1155`, `erc777` or `erc4626`; `native` for the chain's own coin.
   */
  standard: string
  /**
   * `symbol()` as the contract declares it — verbatim, not verified: a contract may declare any text. Absent when the contract declares none. Absent when longer than 64 characters — left out whole, never shortened.
   */
  symbol?: string
  /**
   * All-time number of transfer events.
   */
