/**
 * One executed call frame of a transaction.
 */
export interface TraceFrame {
  /**
   * The frame's address in the call tree, as TraceFast encodes it: four hex characters per level, the root frame is `0000`.
   */
  callPath: string
  /**
   * `call`, `callcode`, `delegatecall`, `staticcall`, `create`, `create2`, `selfdestruct`, `eoa_transfer`.
   */
  callType: string
  /**
   * The frame's position among the frames called by the same parent, from `0`, in the order the parent made the calls: `0` is the parent's first call. The top-level call has no siblings and is `0`. Equal to the last four hex characters of `callPath`.
   */
  childIndex: number
  /**
   * The address whose code this frame runs. On a `delegatecall` this is the implementation while `to` stays the storage context — the PAIR is what makes a proxy call readable, which is why `to` does not change meaning. When this address is an account with an EIP-7702 delegation, the code that ran is its delegate's: `executedCodeAddress`. Absent where there is no callee code (`create`, `create2`, `selfdestruct`).
   */
  codeAddress?: string
  /**
   * The address a `create` / `create2` frame deployed.
   */
  createdAddress?: string
  /**
   * The frame's decoded call. A nested frame's is decoded from `inputHead`: in full when the head is the whole calldata, otherwise from the head only (`byteCoverage: head`). The root frame's (depth 1) is decoded from the transaction's whole calldata exactly as `get_transaction` decodes it — the same status, signature and values; a value too large for a trace is `withheld_for_size`. Present wherever `inputHead` is served.
   */
  decodedCall?: DecodedCall
  /**
   * The authorization that set that delegation. Present exactly when `executedCodeAddress` is.
   */
  delegation?: FrameDelegation
  /**
   * Depth in the tree; `1` is the top-level call — the only frame at depth `1`, so `depth == 1` is how to recognise it.
   */
  depth: number
  /**
   * How it failed: `Revert`, `Panic`, `CustomError`, `OutOfGas`, …
   */
  errorKind?: string
  /**
   * The custom error's 4-byte selector — the ERROR selector, not `inputSelector`.
   */
  errorSelector?: string
  /**
   * The code that actually ran when `codeAddress` is an account with an EIP-7702 delegation in force at this frame: the delegate the account points at. Present only on such frames. Where the response's `delegatedCode.status` is `resolved`, a frame without it ran its own code; while it is `pending`, absence says nothing yet.
   */
  executedCodeAddress?: string
  /**
   * The caller of the frame, lowercase and `0x`-prefixed.
   */
  from: string
  /**
   * Gas offered to the frame, as a decimal string.
   */
  gas: string
  /**
   * Gas the frame consumed, as a decimal string.
   */
  gasUsed: string
  /**
   * Keccak-256 of the init code, `0x`-prefixed. Present only on a creating frame (`create`, `create2`).
   */
  initCodeHash?: string
  /**
   * The first 260 bytes of the frame's calldata, `0x`-hex. Present when calldata heads are included: always on the paged frames, and on the whole trace when `includeCalldata` is true.
   */
  inputHead?: string
  /**
   * The called function's 4-byte selector.
   */
  inputSelector?: string
  /**
   * Full length of the frame's calldata in BYTES. Compare it against 260, not against the hex string's length: the units differ. Present with `inputHead`.
   */
  inputSize?: number
  /**
   * `true` when `inputHead` is shorter than the frame's calldata (`inputSize` is larger than the head's length in bytes): the head is the first bytes only. Present exactly when `inputHead` is.
   */
  inputTruncated?: boolean
  /**
   * Position in pre-order traversal of the call tree; `0` is the transaction's own top-level call.
   */
  order: number
  /**
   * The first 260 bytes of the frame's output, `0x`-hex. Present with `inputHead`.
   */
  outputHead?: string
  /**
   * Full length of the frame's output in BYTES. Compare it against 260, not against the hex string's length. Present with `inputHead`.
   */
  outputSize?: number
  /**
   * The `callPath` of the frame that made this call. Absent on the root frame.
   */
  parentPath?: string
  /**
   * The raw ABI revert payload, `0x`-prefixed hex. It may be truncated — `revertDataTruncated` says when, and a clipped payload decodes into a plausible but wrong argument list, so check the flag before decoding. Absent when there is no payload to state.
   */
  revertData?: string
  /**
   * Full length of the revert payload in BYTES, whether or not `revertData` is truncated. Absent with `revertData`.
   */
  revertDataSize?: number
  /**
   * `true` when `revertData` is shorter than the payload (`revertDataSize`). Absent with `revertData`.
   */
  revertDataTruncated?: boolean
  /**
   * How `revertReason` was found. Present only when `revertDecodeStatus` is `decoded`. `standard`: decoded from the revert payload itself — a standard `Error(string)` message or a `Panic(uint256)` code. `registry`: a custom error — `revertReason` is the error's name, found by its 4-byte selector (`errorSelector`) among known error signatures; its arguments are not decoded (read them from `revertData`).
   */
  revertDecodeSource?: RevertDecodeSource
  /**
   * Why `revertReason` is what it is: `decoded`, `undecodable` (a payload is present but no name was found) or `absent` (no payload to decode). An empty reason is ambiguous three ways, and this field is what separates them.
   *
   * Named apart from the event decoder's `decodeStatus` on purpose: that vocabulary describes event-decode confidence and the two appear in one response.
   */
  revertDecodeStatus?: string
  /**
   * The decoded revert reason, or the custom error's name when its selector is known.
   */
  revertReason?: string
  /**
   * The `create2` salt, 32 bytes, `0x`-prefixed. Present only on a `create2` frame.
   */
  salt?: string
  /**
   * Who received the balance of a `selfdestruct` frame.
   */
  selfdestructBeneficiary?: string
  /**
   * `success`, `reverted` or `halted` — the FRAME's own outcome, which on a caught revert differs from the transaction's.
   */
  status: string
  /**
   * The frame's target. Absent on a contract creation.
   */
  to?: string
  /**
   * Value this frame moved, in wei, as a decimal string.
   */
  valueWei: string
}

