/**
 * One token transfer a transaction emitted. The transaction's own hash, block, time, sender and target are the transaction's fields and are not repeated here.
 */
export interface TransactionTokenTransfer {
  /**
   * Position inside an ERC-1155 `TransferBatch`; `0` for every other event.
   */
  batchIndex: number
  /**
   * `transfer`, `transfer_single`, `transfer_batch`, `sent`, `minted`, `burned`, `deposit`, `withdraw`, `wrap` or `unwrap`. `deposit` and `withdraw` are vault (ERC-4626) events; `wrap` and `unwrap` are ether wrapped into and unwrapped from WETH.
   */
  eventType: string
  /**
   * Whose balance decreased. Absent on a mint and on a `wrap`.
   */
  from?: string
  /**
   * The log's index within the block.
   */
  logIndex: number
  /**
   * The party that executed an approved transfer (ERC-1155 and ERC-777 `operator`), when the log names one.
   */
  operator?: string
  /**
   * Whose balance increased. Absent on a burn and on an `unwrap`.
   */
  to?: string
  /**
   * The token that moved.
   */
  token: TransactionTransferToken
  /**
   * The NFT's token id, as a decimal string.
   */
  tokenId?: string
  /**
   * Raw amount as a decimal string, unscaled by `decimals`. Absent where the standard carries no amount (ERC-721).
   */
  value?: string
}

/**
 * The call tree of one transaction, in pre-order.
 */
export interface TransactionTrace {
  /**
   * Height of the block that includes the transaction.
   */
  blockNumber: number
  /**
   * Whether `executedCodeAddress` is decided for this transaction's frames.
   */
  delegatedCode: DelegatedCodeStatus
  /**
   * Frames in this response. Equal to the tree's size unless `framesTruncated`.
   */
  frameCount: number
  /**
   * The frames of this response, in pre-order: the order in which they ran, `order` `0` first.
   */
  frames: Array<TraceFrame>
  /**
   * `true` when the tree holds more frames than this response — past the `limit` asked for, past the 1 000-frame cap, or past what the response holds of the frames' calldata, revert texts and call paths — and this is its first `frameCount` frames in the order they ran. A clipped tree never claims to be the whole one.
   */
  framesTruncated: boolean
  /**
   * The transaction, lowercase and `0x`-prefixed.
   */
  hash: string
  /**
   * Frames in the WHOLE tree, whatever `limit` asked for — so a small `limit` still says how large the trace is. Absent when the tree is larger than the 1 000-frame cap: its size is then not known here, only that it exceeds the cap.
   */
  totalFrameCount?: number
  /**
   * Position of the transaction within its block, from `0`.
   */
  txIndex: number
}

/**
 * Response of the transaction-trace method.
 */
export interface TransactionTraceResponse {
  /**
   * The answer itself: what this method returns, described by its own schema.
   */
  data: TransactionTrace
  /**
   * Response metadata: when it was produced, whether it came from the cache, the block it is current as of where the method states one, and the link to its documentation.
   */
  meta: PublicMeta
}

/**
 * The token a transaction's transfer moved, as the contract declares itself.
 */
export interface TransactionTransferToken {
  /**
   * The token contract, lowercase and `0x`-prefixed. It is what identifies the token — the symbol does not.
   */
  address: string
  /**
   * Declared decimals. Absent when the contract declares none — never a default `18`.
   */
  decimals?: number
  /**
   * `erc20`, `erc721`, `erc1155`, `erc777`, `erc4626`, … Other values may be added.
   */
  standard: string
  /**
   * The symbol as the contract DECLARES it. Anyone can deploy a token that calls itself `ETH` or `USDT`: a symbol here is not a statement that the token is the well-known one. Check the address. Absent when unknown or longer than 64 characters — a longer symbol is left out whole, never shortened.
   */
  symbol?: string
}

/**
 * The committed transient writes of a transaction, in execution order. Empty for a computed transaction means "no transient writes".
 */
export interface TransactionTransientWrites {
  /**
   * Chain id. `1` is Ethereum mainnet.
   */
  chainId: number
  /**
   * The transaction, lowercase and `0x`-prefixed.
   */
  hash: string
  /**
   * More writes than the cap (5 000): these are the first ones.
   */
  truncated: boolean
  /**
   * The committed transient writes, in execution order. Empty means the transaction made none.
   */
  writes: Array<TransientWrite>
}

/**
 * Response of the transient-writes method.
 */
export interface TransactionTransientWritesResponse {
  /**
   * The answer itself: what this method returns, described by its own schema.
   */
  data: TransactionTransientWrites
  /**
   * Response metadata: when it was produced, whether it came from the cache, the block it is current as of where the method states one, and the link to its documentation.
   */
  meta: PublicMeta
}

/**
 * The token a transfer moved, as the contract declares itself. Same words as the token method; no price and no name from any resolver.
 */
export interface TransferToken {
  /**
   * The token contract. It is what identifies the token — the symbol and the name do not.
   */
  address: string
  /**
   * Declared decimals. Absent when the contract declares none — never a default `18`, which would silently misprice every amount.
   */
  decimals?: number
  /**
   * The name as the contract declares it; self-declared, like `symbol`. Absent when longer than 128 characters — left out whole, never shortened.
   */
  name?: string
  /**
   * `erc20`, `erc721`, `erc1155`, `erc777`, `erc4626`, …
   */
  standard: string
  /**
   * The symbol as the contract DECLARES it. Anyone can deploy a token that calls itself `ETH` or `USDT`: a symbol here is not a statement that the token is the well-known one. Check the address. Absent when longer than 64 characters — left out whole, never shortened.
   */
  symbol?: string
}

/**
 * One committed TSTORE (EIP-1153; none before block 19 426 976).
 */
export interface TransientWrite {
  /**
   * The frame's depth, 1 = the top-level call.
   */
  callDepth: number
  /**
   * The writing frame's path, as on the trace and storage-write methods (join by this).
   */
  callPath?: string
  /**
   * `CALL`, `DELEGATECALL`, …
   */
  callType: string
  /**
   * The caller of the writing frame.
   */
  callerAddress: string
  /**
   * The code that executed the TSTORE (differs from `storageAddress` under DELEGATECALL).
   */
  executionAddress: string
  /**
   * The value written, 32 bytes, `0x`-prefixed.
   */
  newValue: string
  /**
   * The contract whose transient storage was written.
   */
  storageAddress: string
  /**
   * The transient slot written, 32 bytes, `0x`-prefixed.
   */
  storageKey: string
  /**
   * The write's order in the transaction. Absent where it is not numbered.
   */
  writeIndex?: number
}

/**
 * One liquidity event of a transaction.
 */
export interface TxLiquidityEvent {
  /**
   * `add` or `remove`.
   */
  action: string
  /**
   * The event as the pool names it, for example `mint`, `burn`, `add_liquidity`.
   */
  eventType: string
  /**
   * How many token legs the event has — present only when `legs` lists fewer (its first 8).
   */
  legCount?: number
  /**
   * The event's token legs, in the event's order: at most 8 (`legCount` says how many it has when there are more).
   */
  legs: Array<TxLiquidityLeg>
  /**
   * The event's index in the block.
   */
  logIndex: number
  /**
   * The pool, lowercase and `0x`-prefixed.
   */
  pool: string
  /**
   * The event's token legs that could be priced.
   */
  pricedLegs: number
  /**
   * The pool's protocol, for example `uniswap` or `curve`.
   */
  protocol: string
  /**
   * The protocol's version, for example `v3`.
   */
  protocolVersion: string
  /**
   * The liquidity provider the event names, where it names one.
   */
  provider?: string
  /**
   * The event's token legs that could not be priced.
   */
  unpricedLegs: number
}

/**
 * One token leg of a liquidity event in a transaction.
 */
export interface TxLiquidityLeg {
  /**
   * `amountRaw` in whole token units (scaled by `decimals`) as a floating-point number — an approximation for display; `amountRaw` is exact. Absent when the decimals are unknown.
   */
  amount?: number
  /**
   * The amount in the token's smallest unit, as a signed decimal string: positive into the pool, negative out of it. The exact amount.
   */
  amountRaw: string
  /**
   * The leg's USD value, as a positive number. Absent when it could not be priced.
   */
  amountUsd?: number
  /**
   * The decimals the token contract declares. Absent when unknown.
   */
  decimals?: number
  /**
   * Whether the leg went into the pool or out of it: `pool_in`, `pool_out`, `zero` or `unknown`.
   */
  direction: string
  /**
   * The USD price of one whole token behind `amountUsd`. Absent when it could not be priced.
   */
  priceUsd?: number
  /**
   * The token's role in the event, as the source states it.
   */
  role: string
  /**
   * The symbol the token contract declares — verbatim, not verified. Absent when unknown. Absent when longer than 64 characters — left out whole, never shortened.
   */
  symbol?: string
  /**
   * The leg's token, lowercase and `0x`-prefixed. Absent when it could not be resolved.
   */
  token?: string
  /**
   * How the leg was valued, as the source states it: `priced` when it carries a USD value, otherwise why it does not.
   */
  valuationStatus: string
}

/**
 * Provisional classification of an address the knowledge graph has not reached yet.
 *
 * Hints are positive and non-exclusive: a freshly deployed token carries both `contract` and `fungible_token`. They are a list, never a set of booleans — a `false` here would read as a negative fact that was never established.
 */
export interface TypeHints {
  /**
   * Newest block among the evidence behind the hints. Present only with `source: hint`.
   */
  evidenceBlock?: number
  /**
   * Hints observed for the address. Vocabulary: `contract`, `fungible_token`, `nft_collection`, `multi_token_collection`, `eoa`. Present only with `source: hint`.
   */
  hints?: Array<string>
  /**
   * Which source answered: `graph` (the knowledge graph knows the address; no hints are served), `hint` (a provisional classification from on-chain evidence, listed in `hints`) or `none` (nothing is known yet — not a verdict).
   */
  source: TypeHintSource
}

/**
 * Which source answered the "what kind of address is this" question.
 */
export type TypeHintSource = "graph" | "hint" | "none" | (string & {})

/**
 * One withdrawal paid out to a validator's withdrawal address.
 */
export interface ValidatorWithdrawal {
  /**
   * The address paid, lowercase and `0x`-prefixed.
   */
  address: string
  /**
   * Amount paid, gwei, decimal string.
   */
  amountGwei: string
  /**
   * The block the withdrawal was included in.
   */
  blockNumber: number
  /**
   * Unix time of the block, seconds. Absent when it could not be resolved yet — the newest blocks take a few seconds — never a placeholder date.
   */
  timestamp?: number
  /**
   * The withdrawal's global index, unique across the chain.
   */
  withdrawalIndex: number
}

/**
 * One page of a validator's withdrawals, newest first, inside a block window.
 *
 * Every request is answered over a window of at most 216 000 blocks (about 30 days): the newest window by default, or the one asked for with `fromBlock` / `toBlock`. The window is echoed in `window`; to read further back, ask again with `toBlock = window.fromBlock - 1`. `nextCursor` pages inside the window only.
 */
export interface ValidatorWithdrawals {
  /**
   * Chain id the facts are about. `1` is Ethereum mainnet.
   */
  chainId: number
  /**
   * Cursor of the next page inside the window. Absent on the window's last page.
   */
  nextCursor?: string
  /**
   * The validator's index in the consensus registry.
   */
  validatorIndex: number
  /**
   * The window this page was answered over.
   */
  window: WithdrawalWindow
  /**
   * Newest first. Empty when the validator was paid nothing in the window — which is also what an index the chain does not know yet answers.
   */
  withdrawals: Array<ValidatorWithdrawal>
}

/**
 * Response of the validator-withdrawals method.
 */
export interface ValidatorWithdrawalsResponse {
  /**
   * The answer itself: what this method returns, described by its own schema.
   */
  data: ValidatorWithdrawals
  /**
   * Response metadata: when it was produced, whether it came from the cache, the block it is current as of where the method states one, and the link to its documentation.
   */
  meta: PublicMeta
}

/**
 * The inclusive block window a page was answered over.
 */
export interface WithdrawalWindow {
  /**
   * Lowest block of the window, inclusive.
   */
  fromBlock: number
  /**
   * Highest block of the window, inclusive.
   */
  toBlock: number
}
